"The Mom Test": "<svg class=\"dg\" viewBox=\"0 0 460 300\" xmlns=\"http://www.w3.org/2000/svg\" preserveAspectRatio=\"xMidYMid meet\" font-family=\"Arial,Helvetica,sans-serif\" role=\"img\"><rect x=\"16.0\" y=\"18.0\" width=\"206.0\" height=\"196.0\" rx=\"4\" fill=\"#f9eded\" stroke=\"#B91C1C\" stroke-width=\"1\"/><rect x=\"238.0\" y=\"18.0\" width=\"206.0\" height=\"196.0\" rx=\"4\" fill=\"#e8f2ec\" stroke=\"#15803D\" stroke-width=\"1\"/><text x=\"119.0\" y=\"39.9\" font-size=\"11\" fill=\"#B91C1C\" text-anchor=\"middle\" font-weight=\"bold\">✗  Bad questions</text><text x=\"341.0\" y=\"39.9\" font-size=\"11\" fill=\"#15803D\" text-anchor=\"middle\" font-weight=\"bold\">✓  Good questions</text><text x=\"119.0\" y=\"73.1\" font-size=\"8.8\" fill=\"#1B2A4A\" text-anchor=\"middle\" font-style=\"italic\">\"Do you think it's a good idea?\"</text><text x=\"341.0\" y=\"73.1\" font-size=\"8.8\" fill=\"#1B2A4A\" text-anchor=\"middle\" font-style=\"italic\">\"When did this last happen?\"</text><text x=\"119.0\" y=\"109.1\" font-size=\"8.8\" fill=\"#1B2A4A\" text-anchor=\"middle\" font-style=\"italic\">\"Would you buy a product that…?\"</text><text x=\"341.0\" y=\"109.1\" font-size=\"8.8\" fill=\"#1B2A4A\" text-anchor=\"middle\" font-style=\"italic\">\"What did you try to solve it?\"</text><text x=\"119.0\" y=\"145.1\" font-size=\"8.8\" fill=\"#1B2A4A\" text-anchor=\"middle\" font-style=\"italic\">\"How much would you pay?\"</text><text x=\"341.0\" y=\"145.1\" font-size=\"8.8\" fill=\"#1B2A4A\" text-anchor=\"middle\" font-style=\"italic\">\"What does it cost you today?\"</text><text x=\"119.0\" y=\"175.9\" font-size=\"8.8\" fill=\"#1B2A4A\" text-anchor=\"middle\" font-style=\"italic\"><tspan x=\"119.0\" dy=\"0.0\">\"What would your dream product</tspan><tspan x=\"119.0\" dy=\"10.4\">do?\"</tspan></text><text x=\"341.0\" y=\"181.1\" font-size=\"8.8\" fill=\"#1B2A4A\" text-anchor=\"middle\" font-style=\"italic\">\"Who else should I talk to?\"</text><text x=\"119.0\" y=\"204.8\" font-size=\"8\" fill=\"#B91C1C\" text-anchor=\"middle\" font-weight=\"bold\">opinions about the future</text><text x=\"341.0\" y=\"204.8\" font-size=\"8\" fill=\"#15803D\" text-anchor=\"middle\" font-weight=\"bold\">facts about the past</text><rect x=\"16.0\" y=\"228.0\" width=\"136.0\" height=\"40.0\" rx=\"4\" fill=\"#f4e5da\" stroke=\"#B45309\" stroke-width=\"1.2\"/><text x=\"84.0\" y=\"245.9\" font-size=\"8.8\" fill=\"#1B2A4A\" text-anchor=\"middle\" font-weight=\"bold\"><tspan x=\"84.0\" dy=\"0.0\">Talk about their life,</tspan><tspan x=\"84.0\" dy=\"10.4\">not your idea</tspan></text><rect x=\"162.0\" y=\"228.0\" width=\"136.0\" height=\"40.0\" rx=\"4\" fill=\"#f4e5da\" stroke=\"#B45309\" stroke-width=\"1.2\"/><text x=\"230.0\" y=\"245.9\" font-size=\"8.8\" fill=\"#1B2A4A\" text-anchor=\"middle\" font-weight=\"bold\"><tspan x=\"230.0\" dy=\"0.0\">Ask about specifics</tspan><tspan x=\"230.0\" dy=\"10.4\">in the past</tspan></text><rect x=\"308.0\" y=\"228.0\" width=\"136.0\" height=\"40.0\" rx=\"4\" fill=\"#f4e5da\" stroke=\"#B45309\" stroke-width=\"1.2\"/><text x=\"376.0\" y=\"245.9\" font-size=\"8.8\" fill=\"#1B2A4A\" text-anchor=\"middle\" font-weight=\"bold\"><tspan x=\"376.0\" dy=\"0.0\">Talk less,</tspan><tspan x=\"376.0\" dy=\"10.4\">listen more</tspan></text><text x=\"230.0\" y=\"291.0\" font-size=\"8.5\" fill=\"#B45309\" text-anchor=\"middle\" font-weight=\"bold\">Compliments are noise · commitment (time, money, reputation) is evidence</text></svg>",
