"AI Act Duties for Deployers": "<svg class=\"dg\" viewBox=\"0 0 460 300\" xmlns=\"http://www.w3.org/2000/svg\" preserveAspectRatio=\"xMidYMid meet\" font-family=\"Arial,Helvetica,sans-serif\" role=\"img\"><text x=\"230.0\" y=\"21.7\" font-size=\"10.5\" fill=\"#1B2A4A\" text-anchor=\"middle\" font-weight=\"bold\">Deployers of high-risk AI systems must…</text><rect x=\"40.0\" y=\"34.0\" width=\"380.0\" height=\"50.0\" rx=\"4\" fill=\"#e6f7f3\" stroke=\"#00B388\" stroke-width=\"1\"/><rect x=\"40.0\" y=\"34.0\" width=\"50.0\" height=\"50.0\" rx=\"4\" fill=\"#00B388\"/><text x=\"65.0\" y=\"65.3\" font-size=\"18\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"bold\">✓</text><text x=\"104.0\" y=\"55.5\" font-size=\"10\" fill=\"#1B2A4A\" text-anchor=\"start\" font-weight=\"bold\">Use in line with the provider's instructions</text><text x=\"104.0\" y=\"72.0\" font-size=\"8.5\" fill=\"#5A6072\" text-anchor=\"start\">technical and organisational measures</text><rect x=\"40.0\" y=\"92.0\" width=\"380.0\" height=\"50.0\" rx=\"4\" fill=\"#e6f7f3\" stroke=\"#00B388\" stroke-width=\"1\"/><rect x=\"40.0\" y=\"92.0\" width=\"50.0\" height=\"50.0\" rx=\"4\" fill=\"#00B388\"/><text x=\"65.0\" y=\"123.3\" font-size=\"18\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"bold\">✓</text><text x=\"104.0\" y=\"113.5\" font-size=\"10\" fill=\"#1B2A4A\" text-anchor=\"start\" font-weight=\"bold\">Assign competent human oversight</text><text x=\"104.0\" y=\"130.0\" font-size=\"8.5\" fill=\"#5A6072\" text-anchor=\"start\">trained, authorised, able to intervene</text><rect x=\"40.0\" y=\"150.0\" width=\"380.0\" height=\"50.0\" rx=\"4\" fill=\"#e6f7f3\" stroke=\"#00B388\" stroke-width=\"1\"/><rect x=\"40.0\" y=\"150.0\" width=\"50.0\" height=\"50.0\" rx=\"4\" fill=\"#00B388\"/><text x=\"65.0\" y=\"181.3\" font-size=\"18\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"bold\">✓</text><text x=\"104.0\" y=\"171.5\" font-size=\"10\" fill=\"#1B2A4A\" text-anchor=\"start\" font-weight=\"bold\">Control input data relevance</text><text x=\"104.0\" y=\"188.0\" font-size=\"8.5\" fill=\"#5A6072\" text-anchor=\"start\">data fit for the intended purpose</text><rect x=\"40.0\" y=\"208.0\" width=\"380.0\" height=\"50.0\" rx=\"4\" fill=\"#e6f7f3\" stroke=\"#00B388\" stroke-width=\"1\"/><rect x=\"40.0\" y=\"208.0\" width=\"50.0\" height=\"50.0\" rx=\"4\" fill=\"#00B388\"/><text x=\"65.0\" y=\"239.3\" font-size=\"18\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"bold\">✓</text><text x=\"104.0\" y=\"229.5\" font-size=\"10\" fill=\"#1B2A4A\" text-anchor=\"start\" font-weight=\"bold\">Keep logs and inform affected persons</text><text x=\"104.0\" y=\"246.0\" font-size=\"8.5\" fill=\"#5A6072\" text-anchor=\"start\">retain logs ≥ 6 months · tell workers and users</text><text x=\"230.0\" y=\"293.0\" font-size=\"8.5\" fill=\"#5A6072\" text-anchor=\"middle\" font-style=\"italic\">Regulation (EU) 2024/1689, Art. 26</text></svg>",
